library(shiny)
library(bslib)
ui <- page_sidebar(
  title = "z scores to probability lookup", 
  sidebar = sidebar(
    sliderInput(
      "z1", "z(blue)", -3.9, 3.9, -1.96, step = 0.01),
  sliderInput(
    "z2", "z(red)", -3.9, 3.9, +1.96, step = 0.01)
  ),  
  
  page_fluid(
  "Normal Distribution",
  plotOutput("normalplot"),
  layout_columns(
    card("P(x smaller than z(blue)):",
    textOutput("prob_z1"), style = "font-size:15px; background-color:#cee8f0"),
    card("P(x larger than z(blue)):",
    textOutput("prob_z1_c"), style = "font-size:15px; background-color:#cee8f0"),
    card("P(x smaller than z(red)):",
    textOutput("prob_z2"), style = "font-size:15px; background-color:#ffeaeb"),
    card("P(x larger than z(red)):",
    textOutput("prob_z2_c"), style = "font-size:15px; background-color:#ffeaeb"),
    card("P(x between z(blue) and z(red)):",
    textOutput("prob_z1_z2"), style = "font-size:15px"),
    card("P(x outside z(blue) and z(red)):",
    textOutput("prob_z1_z2_out"), style = "font-size:15px"),

  )
))

server <- function(input, output) {
  output$normalplot <- renderPlot({
    x <- seq(from = - 3.9, to = 3.9, by = 0.01)
    p <- (1/(sqrt(2*pi))) * exp(1)^ -((x)^2 / (2*(1^2)))
    plot(x, p, type = "l", lwd = 2)
    abline(h=0, col="black", lwd=2)
    abline(v=input$z1, col="blue", lwd=2)
    abline(v=input$z2, col="red", lwd=2)
  })
  output$prob_z1 <- renderText({
    round(pnorm(input$z1), digits=3)
    })
  output$prob_z1_c <- renderText({
    round(1-pnorm(input$z1), digits=3)
  })
  output$prob_z2 <- renderText({
    round(pnorm(input$z2), digits=3)
  })
  output$prob_z2_c <- renderText({
    round(1-pnorm(input$z2), digits=3)
  })
  output$prob_z1_z2 <- renderText({
    if (input$z1 < input$z2)
      {round((pnorm(input$z2)-pnorm(input$z1)), digits=3) }
    else if (input$z2 < input$z1) 
      {round((pnorm(input$z1)-pnorm(input$z2)), digits=3) }    
    else 
      {print(0)}
  })
  output$prob_z1_z2_out <- renderText({
    if (input$z1 < input$z2)
    {round((pnorm(input$z1)+(1-pnorm(input$z2))), digits=3) }
    else if (input$z2 < input$z1) 
    {round((pnorm(input$z2)+(1-pnorm(input$z1))), digits=3) }
    else 
    {print(0)}
  })
}
shinyApp(ui, server)
